import { NextRequest,NextResponse } from 'next/server';
import { getContext } from '@/lib/authz';
export async function GET(req:NextRequest){const plate=String(req.nextUrl.searchParams.get('plate')||'').replace(/[^A-Z0-9]/gi,'').toUpperCase();if(plate.length<6)return NextResponse.json({found:false});const {profile}=await getContext();if(!profile)return NextResponse.json({error:'Sem sessão'},{status:401});const base=process.env.PLATE_API_URL;const token=process.env.PLATE_API_TOKEN;if(!base)return NextResponse.json({configured:false,found:false});const url=new URL(base);url.searchParams.set('plate',plate);const headers:Record<string,string>={Accept:'application/json'};if(token)headers.Authorization=`Bearer ${token}`;try{const r=await fetch(url,{headers,cache:'no-store'});const d=await r.json().catch(()=>({}));if(!r.ok)return NextResponse.json({configured:true,found:false,error:'Consulta externa indisponível'});const make=d.make??d.marca??d.brand??null;const model=d.model??d.modelo??null;const color=d.color??d.cor??null;const year=d.year??d.ano??null;return NextResponse.json({configured:true,found:Boolean(make||model||color),vehicle:{make,model,color,year}})}catch{return NextResponse.json({configured:true,found:false,error:'Falha ao consultar provedor de placa'})}}
